WITH sales_by_demo AS ( SELECT ss_hdemo_sk, SUM(ss_net_profit) AS total_net_profit, SUM(ss_net_paid) AS total_net_paid, COUNT(*) AS txn_count, AVG(ss_quantity) AS avg_quantity FROM store_sales WHERE ss_sold_date_sk BETWEEN 2450000 AND 2453650 AND ss_quantity > 0 GROUP BY ss_hdemo_sk ) SELECT hd.hd_buy_potential, hd.hd_vehicle_count, d.total_net_profit, d.total_net_paid, d.txn_count, d.avg_quantity, ROUND(d.total_net_profit / NULLIF(d.total_net_paid, 0), 4) AS profit_margin, d.total_net_profit * (1 + (SELECT AVG(cc_tax_percentage) FROM call_center) / 100) AS total_net_profit_adj, ROW_NUMBER() OVER (PARTITION BY hd.hd_buy_potential ORDER BY d.total_net_profit DESC) AS profit_rank FROM sales_by_demo d JOIN household_demographics hd ON d.ss_hdemo_sk = hd.hd_demo_sk WHERE hd.hd_dep_count IS NOT NULL AND d.total_net_profit > 1000 ORDER BY d.total_net_profit DESC LIMIT 20
